const errors=[];page.on('pageerror',e=>errors.push(e.message));
await page.goto('http://localhost:5173');
const button=page.getByRole('button',{name:'Действия'});
await button.click();
await page.getByText('Редактировать',{exact:true}).waitFor({state:'visible'});
await page.screenshot({path:'/tmp/actions-desktop.png',fullPage:true});
