if(await button.getAttribute('aria-expanded')"'!=='"'false')throw Error('Escape did not close menu');
await button.click();await page.locator('h1').click();
if(await button.getAttribute('aria-expanded')"'!=='"'false')throw Error('Outside click did not close menu');
await button.click();await page.getByText('Редактировать',{exact:true}).click();
await page.getByLabel('Название проекта').fill('Новая айдентика Forma');
await page.getByRole('button',{name:'Сохранить',exact:true}).click();
await page.getByRole('heading',{name:'Новая айдентика Forma',exact:true}).waitFor();
await button.click();await page.getByText('Создать копию',{exact:true}).click();
await page.getByText('Новая айдентика Forma — копия',{exact:true}).waitFor();
await button.click();await page.getByText('Архивировать',{exact:true}).click();
await page.getByText('В архиве',{exact:true}).waitFor();
await button.click();await page.getByText('Вернуть из архива',{exact:true}).click();
await page.getByText('В работе',{exact:true}).waitFor();
await button.click();const downloaded=page.waitForEvent('download');await page.getByText('Скачать проект',{exact:true}).click();console.log('Download:',(await downloaded).suggestedFilename());
await page.setViewportSize({width:390,height:844});
await button.click();await page.getByText('Редактировать',{exact:true}).waitFor({state:'visible'});
await page.screenshot({path:'/tmp/actions-mobile.png',fullPage:true});
const overflow=await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth);
if(overflow)throw Error('Mobile horizontal overflow');
if(errors.length)throw Error(errors.join('\\n'));
console.log('PASS: menu click, Escape, outside click, rename, duplicate, archive/restore, download, mobile layout, no runtime errors.');
await browser.close();
JS"

