    grid: <><rect x=\"3\" y=\"3\" width=\"6\" height=\"6\" rx=\"1\" /><rect x=\"15\" y=\"3\" width=\"6\" height=\"6\" rx=\"1\" /><rect x=\"3\" y=\"15\" width=\"6\" height=\"6\" rx=\"1\" /><rect x=\"15\" y=\"15\" width=\"6\" height=\"6\" rx=\"1\" /></>,
