export function App() {
  const [menuOpen, setMenuOpen] = useState(false);
  const [title, setTitle] = useState('Брендинг студии Forma');
  const [draft, setDraft] = useState(title);
  const [editing, setEditing] = useState(false);
  const [archived, setArchived] = useState(false);
  const [notice, setNotice] = useState('');
  const [copies, setCopies] = useState<string[]>([]);
  const toastTimer = useRef<ReturnType<typeof setTimeout>>();
  const notify = (message: string) => {
    setNotice(message);
    clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setNotice(''), 4200);
  };
  useEffect(() => () => clearTimeout(toastTimer.current), []);

  const download = () => {
    const file = new Blob(["'`${title}'"\\n\\nСоздаём визуальный язык независимой дизайн-студии. От идеи и стратегии до айдентики, которая говорит сама за себя.\\n\\nСтатус: "'${archived ? '"'В архиве' : 'В работе'}\\nУчастники: Анна Смирнова, Максим Волков, Екатерина Белова\\n"'`], { type: '"'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(file);
    const a = document.createElement('a');
    a.href = url;
    a.download = "'`${title}.txt`;
    a.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    notify('"'Информация о проекте скачана');
  };

  return (
    <div className=\"app-shell\">
      <header className=\"topbar\">
        <div className=\"brand\"><span className=\"brand-symbol\"><span /><span /><span /></span>дело<span className=\"brand-dot\">.</span></div>
        <div className=\"workspace\"><span className=\"workspace-divider\" />Рабочее пространство<span className=\"workspace-label\">Личное</span></div>
        <div className=\"profile\" aria-label=\"Профиль Анны Смирновой\">АС</div>
      </header>

      <main>
        <div className=\"breadcrumb\"><Icon name=\"grid\" size={15} /><span>Проекты</span><span className=\"breadcrumb-slash\">/</span><span>Детали проекта</span></div>
        <div className=\"page-heading\"><div><div className=\"eyebrow\">ПРОСТРАНСТВО ДЛЯ ВАШИХ ИДЕЙ</div><h1>Хорошая работа начинается здесь<span>.</span></h1><p>Все детали, люди и возможности вашего проекта — в одном месте.</p></div><span className=\"project-number\">ПРОЕКТ / 001</span></div>

        <article className=\"project-card\">
          <div className=\"project-toolbar\">
            <div className=\"project-heading\"><span className=\"project-icon\"><Icon name=\"folder\" size={23} /></span><div><div className=\"project-label\">ДИЗАЙН И АЙДЕНТИКА</div><h2>{title}</h2></div></div>
            <DropdownMenu
              open={menuOpen}
              onOpenToggle={setMenuOpen}
              size=\"l\"
              popupProps={{ placement: 'bottom-end', offset: 8, className: 'actions-popup' }}
              renderSwitcher={(props) => <Button {...props} size=\"l\" view=\"normal\" className={"'`actions-button ${menuOpen ? '"'is-open' : ''}"'`} aria-haspopup="menu" aria-expanded={menuOpen}><span className="actions-button-content">Действия<Icon name="chevron" size={16} /></span></Button>}
              items={[
                [
                  { text: '"'Редактировать', iconStart: <Icon name=\"edit\" />, action: () => { setDraft(title); setEditing(true); } },
                  { text: 'Создать копию', iconStart: <Icon name=\"copy\" />, action: () => { const copy = "'`${title} — копия${copies.length ? ` ${copies.length + 1}` : '"''}"'`; setCopies([...copies, copy]); notify('"'Копия проекта создана'); } },
                ],
                [
                  { text: 'Скопировать ссылку', iconStart: <Icon name=\"link\" />, action: async () => { try { await navigator.clipboard.writeText("'`${location.origin}${location.pathname}#project-001`); notify('"'Ссылка на проект скопирована'); } catch { notify('Не удалось скопировать ссылку. Попробуйте ещё раз.'); } } },
                  { text: 'Скачать проект', iconStart: <Icon name=\"download\" />, action: download },
                ],
                [{ text: archived ? 'Вернуть из архива' : 'Архивировать', iconStart: <Icon name=\"archive\" />, action: () => { setArchived("'!archived); notify(archived ? '"'Проект возвращён в работу' : 'Проект перемещён в архив'); } }],
              ]}
            />
          </div>

          <div className=\"project-art\" role=\"img\" aria-label=\"Обложка проекта Forma: геометрическая зелёная композиция\">
            <div className=\"art-copy\"><span className=\"art-kicker\">НЕЗАВИСИМАЯ ДИЗАЙН-СТУДИЯ</span><span className=\"forma-word\">forma<span>®</span></span><span className=\"art-caption\">Придаём идеям форму.</span></div>
            <div className=\"art-shapes\"><div className=\"shape-circle\" /><div className=\"shape-arch\" /><div className=\"shape-square\" /><div className=\"shape-small-circle\" /></div>
            <div className=\"art-bottom\"><span>BRAND IDENTITY — 2026</span><span>Идея. Характер. Форма. <Icon name=\"arrow\" size={17} /></span></div>
          </div>

          <div className=\"project-meta\"><div className=\"meta-item\"><span className=\"meta-label\">Статус</span><span className={"'`status ${archived ? '"'archived' : ''}"'`}><span />{archived ? '"'В архиве' : 'В работе'}</span></div><div className=\"meta-item\"><span className=\"meta-label\">Дата создания</span><span className=\"meta-value\">20 октября 2026</span></div><div className=\"meta-item\"><span className=\"meta-label\">Участники</span><div className=\"mini-team\"><span className=\"mini-avatar avatar-one\">АС</span><span className=\"mini-avatar avatar-two\">МВ</span><span className=\"mini-avatar avatar-three\">ЕБ</span><span className=\"team-count\">3 человека</span></div></div><div className=\"meta-item update-meta\"><span className=\"meta-label\">Обновлено</span><span className=\"meta-value\">Сегодня, 10:42</span></div></div>
        </article>

        <div className=\"details-grid\"><section className=\"description-panel\"><div className=\"section-heading\"><span className=\"section-mark\" /><h3>О проекте</h3></div><p>Создаём визуальный язык независимой дизайн-студии. От идеи и стратегии до айдентики, которая говорит сама за себя.</p><div className=\"tags\"><span>Брендинг</span><span>Дизайн</span><span>Стратегия</span></div></section><section className=\"owner-panel\"><div className=\"section-heading\"><span className=\"section-mark\" /><h3>Ответственный</h3></div><div className=\"owner\"><span className=\"owner-avatar\">АС</span><div><strong>Анна Смирнова</strong><span>Арт-директор</span></div><span className=\"owner-badge\">Владелец</span></div></section></div>
        {copies.length > 0 && <section className=\"copies-panel\"><h3>Копии проекта</h3>{copies.map((copy) => <div className=\"copy-row\" key={copy}><Icon name=\"folder\" /><span>{copy}</span><span className=\"copy-tag\">Новый проект</span></div>)}</section>}
        <footer><span className=\"footer-dot\" />Больше порядка. Больше пространства для идей.<span className=\"footer-brand\">Сделано в деле.</span></footer>
      </main>

      <Modal open={editing} onClose={() => setEditing(false)} aria-labelledby=\"edit-title\">
        <form className=\"edit-modal\" onSubmit={(event) => { event.preventDefault(); if ("'!draft.trim()) return; setTitle(draft.trim()); setEditing(false); notify('"'Название проекта сохранено'); }}>
          <div className=\"modal-heading\"><h2 id=\"edit-title\">Редактировать проект</h2><Button view=\"flat\" aria-label=\"Закрыть\" onClick={() => setEditing(false)}><Icon name=\"close\" /></Button></div>
          <label htmlFor=\"project-title\">Название проекта</label><TextInput id=\"project-title\" value={draft} onUpdate={setDraft} autoFocus size=\"l\" maxLength={100} />
          <div className=\"modal-buttons\"><Button size=\"l\" onClick={() => setEditing(false)}>Отмена</Button><Button className=\"save-button\" size=\"l\" type=\"submit\" disabled={"'!draft.trim()}>Сохранить</Button></div>
        </form>
      </Modal>
      {notice && <div className="toast" role="status"><span className="toast-check"><Icon name="check" size={15} /></span>{notice}<button aria-label="Закрыть уведомление" onClick={() => setNotice('"'')}><Icon name=\"close\" size={15} /></button></div>}
    </div>
  );
}
